import {projects,techniques,tools,categories,videoResources} from './data.js';
import {initialState,loadState,saveState,completedSteps,nextStep,setStep,dimensionGuide,validVideoURL} from './store.js';
import {analyzePhoto,prepareImage} from './analysis-service.js';
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1v15"/>',heart:'<path d="M20.8 4.6c-2-2-5.3-1.8-7.2.3L12 6.6l-1.6-1.7C8.5 2.8 5.2 2.6 3.2 4.6c-2 2-2 5.4 0 7.5L12 21l8.8-8.9c2-2.1 2-5.5 0-7.5Z"/>',upload:'<path d="M4 15v5h16v-5M12 16V3m-5 5 5-5 5 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',play:'<path d="m9 5 11 7-11 7z"/>',check:'<path d="m4 12 5 5L20 6"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage;try{storage=window.localStorage;}catch{}
let state=storage?loadState(storage):initialState();
let filter='すべて',dictionaryGroup='すべて',draftImage=null,draftResult=null,uploadSequence=0,draftTemplate='lamp',draftDimensions={...projects[0].dimensions};
const allProjects=()=>[...projects,...state.customProjects];
const projectById=id=>allProjects().find(p=>p.id===id);
const techById=id=>techniques.find(t=>t.id===id);
const navs=[['home','home','ホーム'],['explore','search','作品を探す'],['dictionary','book','編み方辞典'],['favorites','heart','お気に入り']];
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function commit(change){const updated=structuredClone(state);change(updated);try{if(!storage)throw new Error('unavailable');saveState(storage,updated);state=updated;return true;}catch{toast('保存できませんでした。ブラウザの保存容量・設定を確認してください。変更は保存されていません。');return false;}}
function progress(p){const n=completedSteps(state,p).length;return `<div class="progress-info"><span>${n===p.steps.length?'すべての工程ができました':`次は：${esc(p.steps[nextStep(state,p)].title)}`}</span><span>${n} / ${p.steps.length} STEP</span></div><progress value="${n}" max="${p.steps.length}" aria-label="${esc(p.name)}の制作進捗"></progress>`;}
function projectImage(p,cls='card-image'){return p.image?`<img class="${cls}" src="${esc(p.image)}" alt="${esc(p.name)}の参考画像">`:`<div class="catalog-art tone${projects.findIndex(x=>x.id===p.id)%3}">${esc(p.short||p.name)}<span class="badge" style="margin-left:auto">サンプル</span></div>`;}
function heart(p){return `<button class="heart" data-favorite="${esc(p.id)}" aria-label="${esc(p.name)}をお気に入り${state.favorites.includes(p.id)?'から解除':'に登録'}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button>`;}
function card(p){return `<article class="card"><a href="#project/${esc(p.id)}">${projectImage(p)}<div class="card-body"><span class="badge">${esc(p.difficulty)}</span><h3>${esc(p.name)}</h3><p class="muted">${esc(p.description)}</p><small>${esc(p.categories[0])} · ${p.steps.length} STEP</small></div></a>${heart(p)}</article>`;}
function back(href,label){return `<a class="back" href="#${href}">${icon('back')}${label}</a>`;}
function techLinks(ids){return `<div class="chips">${ids.map(id=>`<a class="chip" href="#technique/${id}">${esc(techById(id)?.name||id)} ↗</a>`).join('')}</div>`;}
function videoBlock(ids){return `<div>${ids.map(id=>{const v=videoResources[id];if(!v)return '';const raw=state.videoOverrides[id];const url=raw&&validVideoURL(raw)?raw:v.url;return `<a class="video-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('play')}<span>参考動画を見る：${esc(v.title)}<small>${raw?'登録した参考URL':`${v.provider}・日本語 ${v.duration}`} ／ 外部ページで開きます ↗</small></span></a>`;}).join('')}<p class="source-note">速いと感じたら、動画を開いて設定から0.25倍・0.5倍・0.75倍を選んでください。対応する速度は動画プレーヤーによって異なります。</p></div>`;}
function supplies(p){return `<div class="columns"><section class="panel"><h2>そろえる道具</h2>${tools.map(t=>`<div class="definition"><b>${t.name}</b><p>${t.description}</p></div>`).join('')}</section><section class="panel"><h2>材料の目安</h2>${p.materials.map(m=>`<div class="definition"><b>${esc(m.name)}</b><p>${esc(m.description)}</p></div>`).join('')}<div class="notice">糸と針はセットで考えましょう。針の号数は写真で決めず、糸のラベルと試し編みで確認します。</div></section></div>`;}
function dimensionFields(values){const keys=values.diameter!==undefined?['diameter','height']:['width','height'];const names={diameter:'直径',height:'高さ',width:'幅'};return `<div class="fields">${keys.map(key=>`<label>${names[key]}（cm）<input type="number" name="${key}" value="${esc(values[key]||'')}" min="0.1" max="500" step="0.1" required inputmode="decimal"></label>`).join('')}</div>`;}
function readDimensions(form){const d={};for(const key of ['diameter','width','height']){const el=form.elements.namedItem(key);if(el){const n=Number(el.value);if(!Number.isFinite(n)||n<.1||n>500)throw new Error('サイズは0.1〜500cmの範囲で入力してください。');d[key]=n;}}return d;}
function dimensionsPanel(p){const d=state.dimensions[p.id]||p.dimensions;return `<section class="panel"><h2>作りたいサイズ</h2><form id="dimensions-form" data-project="${esc(p.id)}">${dimensionFields(d)}<button class="btn" type="submit">サイズを保存</button></form><p class="muted" style="margin:16px 0 0">${esc(dimensionGuide(d))}</p></section>`;}
function home(){const active=allProjects().filter(p=>state.progress[p.id]!==undefined);const current=active.length?active.slice().reverse():[projects[0]];return `<div class="page-head"><div class="eyebrow">YOUR LITTLE CRAFT TIME</div><h1>今日は、何を編みましょう。</h1><p class="muted">「作ってみたい」を、ひと目ずつ形に。</p></div><section class="hero"><div class="hero-copy"><div class="eyebrow">写真から、はじめる</div><h1>この「好き」を、<br>自分の手で。</h1><p>作ってみたい編み物の写真を追加すると、<br>必要な道具や編み方を一緒に考えます。</p><a href="#upload" class="btn primary">${icon('upload')} 写真から作り方を調べる ${icon('arrow')}</a><small>いまはサンプルで体験できます。写真は外部送信しません。</small></div><img src="assets/lamp.png" alt="生成された参考イメージ：透かし編みのランプカバーと毛糸"></section><div class="section-head"><h2>制作中の作品</h2><span class="muted" style="font-size:13px">あなたのペースで</span></div><div class="stack">${current.map(p=>{const started=state.progress[p.id]!==undefined;return `<section class="continue">${projectImage(p)}<div><span class="badge green">${started?'制作ノート':'サンプルからはじめる'}</span><h3>${esc(p.name)}</h3>${progress(p)}</div><a class="btn" href="#${started?`step/${p.id}/${nextStep(state,p)}`:`project/${p.id}`}">${started?'続きから':'作品を見る'} ${icon('arrow')}</a></section>`;}).join('')}</div><div class="section-head"><h2>次に、作ってみたいもの</h2><a href="#explore">すべて見る →</a></div><div class="cards">${projects.slice(1,4).map(card).join('')}</div><div class="learn-strip">${icon('book')}<div><h3>はじめの一目から、一緒に。</h3><p class="muted">分からない編み方は、いつでも辞典で。</p></div><a class="btn" href="#dictionary">編み方を学ぶ ${icon('arrow')}</a></div>`;}
function explore(favorites=false){const list=allProjects().filter(p=>(!favorites||state.favorites.includes(p.id))&&(favorites||filter==='すべて'||p.categories.includes(filter)));return `<div class="page-head"><div class="eyebrow">${favorites?'SAVED FOR LATER':'FIND YOUR NEXT PROJECT'}</div><h1>${favorites?'お気に入り':'次の「作ってみたい」を探す。'}</h1><p class="muted">${favorites?'いつか編みたいものを、ここに。':'小さなものから、少しずつ。気になる作品を選んでみましょう。'}</p></div>${favorites?'':`<div class="chips" style="margin-bottom:28px">${categories.map(c=>`<button data-category="${c}" class="chip ${filter===c?'active':''}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div>`}<p class="source-note">${list.length}作品 · 作品と手順は練習用のサンプルです。正確な編み図ではありません。</p>${list.length?`<div class="cards">${list.map(card).join('')}</div>`:`<div class="empty"><h2>${favorites?'まだ、お気に入りはありません。':'このカテゴリーの作品は準備中です。'}</h2><p class="muted">作品カードのハートを押すと、ここに保存できます。</p><a href="#explore" class="btn">作品を探す</a></div>`}`;}
function upload(){return `${back('home','ホームへ')}<div class="narrow"><div class="page-head"><div class="eyebrow">START WITH A PHOTO</div><h1>作りたいものの写真を追加</h1><p class="muted">気になる形や模様から、はじめの一歩を。</p></div><div class="notice"><b>サンプルモード</b><br>現在は画像を解析せず、選んだ作品のサンプル結果を表示します。写真はこの端末だけで扱い、外部に送信しません。</div><form id="upload-form" class="panel"><div class="upload-zone" id="dropzone"><div id="image-preview" aria-live="polite">${draftImage?`<img src="${esc(draftImage)}" alt="追加した写真">`:`${icon('upload')}<p><b>写真を選ぶ、またはここにドロップ</b></p><small>JPEG・PNG・WebP ／ 10MBまで</small>`}</div><label for="photo" class="btn" style="display:inline-flex;margin-top:16px">${draftImage?'写真を変更':'写真ライブラリから選ぶ'}</label><input id="photo" name="photo" type="file" accept="image/jpeg,image/png,image/webp" aria-label="作りたいものの写真"></div><p class="error" id="upload-error" role="alert"></p><label>体験するサンプル<select id="template" name="template">${projects.map(p=>`<option value="${p.id}" ${p.id===draftTemplate?'selected':''}>${p.name}</option>`).join('')}</select></label><p class="source-note">写真の内容にかかわらず、ここで選んだ作品が結果に表示されます。</p><h3 style="margin-top:24px">作りたいサイズ</h3><div id="upload-dimensions">${dimensionFields(draftDimensions)}</div><button id="analyze" type="submit" class="btn primary full" ${draftImage?'':'disabled'}>サンプルの提案を見る ${icon('arrow')}</button></form></div>`;}
function result(){if(!draftResult)return `<div class="empty"><h1>写真を追加してはじめましょう。</h1><a class="btn primary" href="#upload">写真を追加</a></div>`;const r=draftResult,p=projectById(r.templateId);return `${back('upload','写真とサイズを変更')}<div class="page-head"><div class="eyebrow">YOUR MAKING PLAN</div><h1>こんな編み方から、はじめてみませんか。</h1></div><div class="notice"><b>写真の解析結果ではありません</b><br>${esc(r.notice)}</div><div class="columns"><img class="result-image" src="${esc(draftImage)}" alt="相談に追加した写真"><section class="panel"><span class="badge">サンプル内での想定</span><h2 style="margin-top:12px">${p.name}</h2><div class="chips">${r.features.map(f=>`<span class="chip">${f}</span>`).join('')}</div><p class="muted" style="margin-top:18px">${esc(r.uncertainty)}</p><b>入力したサイズ</b><p>${esc(dimensionGuide(r.dimensions))}</p></section></div><section class="panel"><div class="eyebrow">初心者向けの提案 · サンプル</div><h2>${techById(r.recommended).name}から、試してみましょう。</h2><p>${esc(r.reason)}</p>${techLinks([r.recommended])}<hr class="divider"><h3>ほかに考えられる編み方</h3>${techLinks(r.candidates.filter(id=>id!==r.recommended))}<p class="source-note" style="margin-top:16px">これらは選択した作品を作る場合の候補です。写真と同じ編み方であることを保証するものではありません。</p></section>${supplies(p)}<section class="panel"><h2>制作の流れ</h2><div class="steps">${p.steps.map((s,i)=>`<div class="step-row"><span>${i+1}</span><b>${s.title}</b></div>`).join('')}</div><button class="btn primary full" id="save-project" style="margin-top:24px">この提案で制作ノートを作る ${icon('arrow')}</button><p class="source-note" style="margin:12px 0 0">写真・サイズ・制作進捗をこのブラウザに保存します。</p></section>`;}
function project(p){if(!p)return missing();const n=completedSteps(state,p).length;return `${back('home','ホームへ')}<div class="detail-head"><div>${projectImage(p)}<p class="source-note">${esc(p.imageNote||'練習用のサンプル作品です。')}</p></div><div><span class="badge">${p.fromPhoto?'写真相談のサンプル':'サンプル作品'}</span><h1>${esc(p.name)}</h1><p class="muted">${esc(p.description)}</p><span class="badge green">${esc(p.difficulty)}</span>${progress(p)}<div class="actions"><button class="btn primary" data-start="${esc(p.id)}">${n?'続きから始める':'この作品をはじめる'} ${icon('arrow')}</button><button class="btn" data-favorite="${esc(p.id)}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}${state.favorites.includes(p.id)?'保存済み':'お気に入り'}</button></div></div></div><div class="notice">この作品は練習用サンプルです。写真どおりに作れる確定レシピではありません。目数・段数は試し編みと採用する編み図で確認してください。${p.id==='lamp'||p.templateId==='lamp'?' ランプへの取り付け方法と耐熱性は未確認です。糸を熱源に近づけないでください。':''}</div>${dimensionsPanel(p)}<details id="project-supplies" class="disclosure"><summary>道具・材料を確認する<span>準備するものを見る</span></summary><div class="disclosure-body">${supplies(p)}</div></details><section class="panel"><h2>使う編み方</h2>${techLinks(p.techniques)}</section><section class="panel"><h2>制作の手順</h2><div class="steps">${p.steps.map((s,i)=>{const done=completedSteps(state,p).includes(s.id);return `<a class="step-row ${done?'done':''}" href="#step/${esc(p.id)}/${i}"><span>${done?'✓':i+1}</span><b>${esc(s.title)}</b><small>${done?'できた':'ひとつずつ見る →'}</small></a>`;}).join('')}</div></section><details id="project-videos" class="disclosure"><summary>参考動画<span>手の動きを確認する</span></summary><div class="disclosure-body">${videoBlock([...new Set(p.steps.flatMap(s=>s.videos))])}</div></details><div class="mobile-dock project-dock"><span>${n} / ${p.steps.length} STEP 完了</span><button class="btn primary" data-start="${esc(p.id)}">${n===p.steps.length?'手順を振り返る':n?'続きから始める':'この作品をはじめる'} ${icon('arrow')}</button></div>`;}
function stepPage(p,index){if(!p||!Number.isInteger(index)||!p.steps[index])return missing();const s=p.steps[index],done=completedSteps(state,p).includes(s.id),count=completedSteps(state,p).length;return `${back(`project/${p.id}`,'作品と手順一覧へ')}<div class="narrow"><p class="muted">${esc(p.name)}</p>${progress(p)}<section class="panel focus-step" style="margin-top:26px"><div class="eyebrow">STEP ${String(index+1).padStart(2,'0')} / ${String(p.steps.length).padStart(2,'0')}</div><h1>${esc(s.title)}</h1><p class="description">${esc(s.description)}</p>${index===0?`<p class="muted">${esc(dimensionGuide(state.dimensions[p.id]||p.dimensions))}</p>`:''}<div class="tip"><strong>ここを、ゆっくり。</strong><p>${esc(s.tip)}</p></div><details id="step-help" class="disclosure"><summary>編み方・参考動画<span>迷ったら、ここで確認</span></summary><div class="disclosure-body">${techLinks(s.techniques)}${videoBlock(s.videos)}</div></details><button class="btn ${done?'':'primary'} full" data-done="${esc(s.id)}" data-project="${esc(p.id)}" aria-pressed="${done}">${icon('check')}${done?'できた！ — 押すと完了を取り消す':'このSTEP、できた'}</button><small style="display:block;text-align:center;margin-top:8px">完了を押すと、このブラウザに保存します。</small></section>${count===p.steps.length?'<div class="notice"><b>すべてのSTEPができました。</b><br>おつかれさまでした。ひと目ずつ、形になりましたね。</div>':''}<div class="actions step-pagination">${index>0?`<a class="btn" href="#step/${esc(p.id)}/${index-1}">← 前のSTEP</a>`:''}${index<p.steps.length-1?`<a class="btn" href="#step/${esc(p.id)}/${index+1}">次のSTEP →</a>`:`<a class="btn" href="#project/${esc(p.id)}">作品に戻る</a>`}</div><div class="mobile-dock step-dock"><span class="dock-caption">STEP ${index+1} / ${p.steps.length} · ${done?'完了済み':'自分のペースで'}</span>${index>0?`<a class="btn dock-back" href="#step/${esc(p.id)}/${index-1}" aria-label="前のSTEPへ">${icon('back')}</a>`:`<a class="btn dock-back" href="#project/${esc(p.id)}" aria-label="手順一覧へ">${icon('book')}</a>`}<button class="btn primary" data-advance="${esc(p.id)}" data-index="${index}">${icon(done?'arrow':'check')}${done?(index===p.steps.length-1?'作品に戻る':'次のSTEPへ'):(index===p.steps.length-1?'できた！ 完成する':'できた、次へ')}</button></div></div>`;}
function dictionary(){const groups=['すべて',...new Set(techniques.map(t=>t.group))];return `<div class="page-head"><div class="eyebrow">ONE STITCH AT A TIME</div><h1>編み方辞典</h1><p class="muted">はじめての言葉も、ひとつずつ。手を動かしながら覚えましょう。</p></div><div class="chips" style="margin-bottom:28px">${groups.map(g=>`<button class="chip ${dictionaryGroup===g?'active':''}" data-group="${g}" aria-pressed="${dictionaryGroup===g}">${g}</button>`).join('')}</div><div class="techniques">${techniques.filter(t=>dictionaryGroup==='すべて'||t.group===dictionaryGroup).map(t=>`<a class="technique" href="#technique/${t.id}"><span class="number">${String(techniques.indexOf(t)+1).padStart(2,'0')}</span><small>${t.group}</small><b>${t.name} ↗</b><p>${t.summary}</p></a>`).join('')}</div><div class="learn-strip">${icon('play')}<div><h3>自分に合う動画を使う</h3><p class="muted">参考動画のURLは、この端末用に変更できます。</p></div><a class="btn" href="#videos">参考動画を管理</a></div>`;}
function technique(t){if(!t)return missing();return `${back('dictionary','編み方辞典へ')}<div class="narrow"><div class="page-head"><span class="badge">${t.group}</span><h1 style="margin-top:16px">${t.name}</h1><p class="description">${t.summary}</p></div><section class="panel"><h2>こんなときに使います</h2><p>${t.use}</p></section><section class="panel"><h2>ゆっくり、手順を確認</h2><div class="stack">${t.steps.map((s,i)=>`<div class="definition"><span class="eyebrow">${String(i+1).padStart(2,'0')}</span><p style="font-size:18px;color:var(--ink)">${s}</p></div>`).join('')}</div><div class="tip"><strong>よくあるつまずき</strong><p>${t.mistakes}</p></div></section><section class="panel"><h2>手の動きを見てみる</h2>${videoBlock(t.videos)}</section></div>`;}
function videos(){return `${back('dictionary','編み方辞典へ')}<div class="narrow"><h1>参考動画を管理</h1><p class="muted">日本語の、手元が見やすい動画を選びましょう。</p><form class="panel" id="video-form"><label>差し替える項目<select name="video" id="video-select">${Object.entries(videoResources).map(([id,v])=>`<option value="${id}">${esc(v.title)}</option>`).join('')}</select></label><label>参考URL<input type="url" name="url" id="video-url" value="${esc(state.videoOverrides.chain||videoResources.chain.url)}" required></label><p class="source-note">YouTubeまたはクロバーのHTTPS URLを登録できます。変更はこのブラウザだけに保存します。</p><div class="actions"><button class="btn primary" type="submit">URLを保存</button><button type="button" class="btn" id="reset-video">この項目を元に戻す</button></div><p class="error" id="video-error" role="alert"></p></form><h2>登録されている参考動画</h2>${videoBlock(Object.keys(videoResources))}</div>`;}
function missing(){return `<div class="empty"><h1>ページが見つかりません。</h1><a class="btn" href="#home">ホームに戻る</a></div>`;}
function render({focus=false}={}){const expanded=focus?[]:[...document.querySelectorAll('details[open][id]')].map(el=>el.id);const active=document.activeElement;const focusKey=active?.dataset.favorite||active?.dataset.category||active?.dataset.group||active?.dataset.done;const [route,id,param]=(location.hash.slice(1)||'home').split('/');document.body.dataset.route=route;$('#nav').innerHTML=navs.map(([key,i,label])=>`<a href="#${key}" class="${route===key||(key==='dictionary'&&['technique','videos'].includes(route))?'active':''}" ${route===key?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('');const views={home,explore:()=>explore(),favorites:()=>explore(true),upload,result,dictionary,technique:()=>technique(techById(id)),project:()=>project(projectById(id)),step:()=>stepPage(projectById(id),Number(param)),videos};$('#main').innerHTML=(views[route]||missing)();document.title=`${$('#main h1')?.textContent||'ホーム'} | ひとあみ`;bindForms();for(const key of expanded){const detail=document.getElementById(key);if(detail)detail.open=true;}if(!focus&&focusKey){const match=[...document.querySelectorAll('button')].find(el=>[el.dataset.favorite,el.dataset.category,el.dataset.group,el.dataset.done].includes(focusKey));match?.focus({preventScroll:true});}if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0);}}
function go(hash){if(location.hash===`#${hash}`)render({focus:true});else location.hash=hash;}
async function acceptPhoto(file){const sequence=++uploadSequence;draftImage=null;draftResult=null;const button=$('#analyze');if(button)button.disabled=true;try{const image=await prepareImage(file);if(sequence!==uploadSequence)return;draftImage=image;const preview=$('#image-preview');if(preview){preview.innerHTML=`<img src="${esc(image)}" alt="追加した写真">`;$('#upload-error').textContent='';$('#analyze').disabled=false;}}catch(e){if(sequence!==uploadSequence)return;const error=$('#upload-error');if(error)error.textContent=e.message;}}
function bindForms(){const form=$('#upload-form');if(form){$('#photo').onchange=e=>{if(e.target.files[0])acceptPhoto(e.target.files[0]);};$('#template').onchange=e=>{draftTemplate=e.target.value;draftDimensions={...projectById(draftTemplate).dimensions};$('#upload-dimensions').innerHTML=dimensionFields(draftDimensions);};form.addEventListener('input',()=>{try{draftDimensions=readDimensions(form);}catch{}});const zone=$('#dropzone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag');};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');if(e.dataTransfer.files[0])acceptPhoto(e.dataTransfer.files[0]);};form.onsubmit=async e=>{e.preventDefault();const button=$('#analyze');button.disabled=true;button.textContent='提案を準備しています…';try{const dimensions=readDimensions(form);draftResult=await analyzePhoto({imageData:draftImage,templateId:form.elements.template.value,dimensions});go('result');}catch(err){$('#upload-error').textContent=err.message;button.disabled=!draftImage;button.textContent='サンプルの提案を見る';}};}
 const sizeForm=$('#dimensions-form');if(sizeForm)sizeForm.onsubmit=e=>{e.preventDefault();try{const d=readDimensions(sizeForm);if(commit(s=>s.dimensions[sizeForm.dataset.project]=d)){render();toast('サイズを保存しました。');}}catch(err){toast(err.message);}};
 const videoForm=$('#video-form');if(videoForm){$('#video-select').onchange=e=>{$('#video-url').value=state.videoOverrides[e.target.value]||videoResources[e.target.value].url;};videoForm.onsubmit=e=>{e.preventDefault();const url=videoForm.elements.url.value.trim();if(!validVideoURL(url)){$('#video-error').textContent='YouTubeまたはクロバーのHTTPS URLを入力してください。';return;}const id=videoForm.elements.video.value;if(commit(s=>s.videoOverrides[id]=url)){render();toast('参考URLを保存しました。');}};$('#reset-video').onclick=()=>{const id=videoForm.elements.video.value;if(commit(s=>delete s.videoOverrides[id])){render();toast('元の参考動画に戻しました。');}};}}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;
 if(button.dataset.favorite){const id=button.dataset.favorite;if(!projectById(id))return;const was=state.favorites.includes(id);if(commit(s=>{s.favorites=was?s.favorites.filter(x=>x!==id):[...s.favorites,id];})){render();toast(was?'お気に入りを解除しました。':'お気に入りに保存しました。');}}
 if(button.dataset.category){filter=button.dataset.category;render();}
 if(button.dataset.group){dictionaryGroup=button.dataset.group;render();}
 if(button.dataset.start){const p=projectById(button.dataset.start);if(commit(s=>{s.progress[p.id]??=[];}))go(`step/${p.id}/${nextStep(state,p)}`);}
 if(button.dataset.advance){const p=projectById(button.dataset.advance),index=Number(button.dataset.index);if(!p?.steps[index])return;if(commit(s=>setStep(s,p,p.steps[index].id,true))){go(index<p.steps.length-1?`step/${p.id}/${index+1}`:`project/${p.id}`);toast('進捗を保存しました。');}}
 if(button.dataset.done){const p=projectById(button.dataset.project),done=completedSteps(state,p).includes(button.dataset.done);if(commit(s=>setStep(s,p,button.dataset.done,!done))){render();toast(done?'完了を取り消しました。':'できた！ 進捗を保存しました。');}}
 if(button.id==='save-project'&&draftResult){const r=draftResult,base=projectById(r.templateId);const id=`photo-${crypto.randomUUID()}`;const p={...structuredClone(base),id,templateId:base.id,fromPhoto:true,name:`${base.short} · 写真からの相談`,image:draftImage,imageNote:'アップロードした参考画像。提案内容は選択したサンプルです。',dimensions:r.dimensions};if(commit(s=>{s.customProjects.push(p);s.progress[id]=[];s.dimensions[id]=r.dimensions;})){draftResult=null;draftImage=null;go(`project/${id}`);toast('制作ノートを保存しました。');}}
});
window.addEventListener('hashchange',()=>render({focus:true}));
window.addEventListener('storage',e=>{if(e.key==='hitoami.v1'){state=loadState(storage);render();}});
render();
if(!storage)toast('このブラウザでは保存を利用できません。');
