const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'list_craft_progress',title:'制作進捗を読む',description:'List locally saved projects and completed step IDs without changing data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>allProjects().map(p=>({id:p.id,name:p.name,steps:p.steps.map(s=>({id:s.id,title:s.title})),completed:completedSteps(state,p)}))});
 register({name:'set_craft_step_complete',title:'工程の完了を保存',description:'Mark or unmark one existing project step as complete and persist locally.',inputSchema:{type:'object',properties:{projectId:{type:'string'},stepId:{type:'string'},completed:{type:'boolean'}},required:['projectId','stepId','completed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.completed!=='boolean'||typeof input.projectId!=='string'||typeof input.stepId!=='string')throw new Error('Invalid input');const p=projectById(input.projectId);if(!p||!p.steps.some(s=>s.id===input.stepId))throw new Error('Unknown project or step');if(!commit(s=>setStep(s,p,input.stepId,input.completed)))throw new Error('Persistence failed');render();return {projectId:p.id,completed:completedSteps(state,p)};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
